// Package postgres implements org.Store against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/errorx"
	"github.com/garamsh/garam/platform/internal/grn"
	"github.com/garamsh/garam/platform/internal/org"
	"github.com/garamsh/garam/platform/internal/org/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
)

// Store implements org.Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql. Deleting an Organization
// cascade-deletes its Groups, Projects, Memberships, and Invitations
// via foreign keys.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that Store satisfies org.Store.
var _ org.Store = (*Store)(nil)

// New constructs a Postgres-backed org.Store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

func parseGRNs(ss []string, op string) ([]grn.GRN, error) {
	out := make([]grn.GRN, 0, len(ss))
	for _, s := range ss {
		g, err := grn.Parse(s)
		if err != nil {
			return nil, errorx.Wrap(err, op, errorx.KindInternal)
		}
		out = append(out, g)
	}
	return out, nil
}

// classifyRows maps the outcome of a statement that reports how many
// rows it touched: a driver error takes pgxerr.Classify, and a
// statement that matched none takes the notFound sentinel. Every
// delete and removal in this store answers through here, so none of
// them reports success for a row that was not there.
func classifyRows(n int64, err error, op string, notFound error) error {
	if err != nil {
		return pgxerr.Classify(err, op, notFound, nil)
	}
	if n == 0 {
		return notFound
	}
	return nil
}

// strs normalizes a nil slice to empty: pgx encodes a nil slice as
// NULL, which the NOT NULL array columns reject.
func strs(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// text converts a *string patch field to a nullable text.
func text(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

// limit converts a list filter's limit: 0 means "no limit" (SQL NULL).
func limit(n int) pgtype.Int4 {
	if n <= 0 {
		return pgtype.Int4{}
	}
	return pgtype.Int4{Int32: int32(n), Valid: true}
}
